	authorSequence: number
): DurableIssueCommit {
	const hasPlanEffect =
		typeof value === "object" && value !== null && Object.prototype.hasOwnProperty.call(value, "planEffect");
	if (
		!isClosedDurableIssuanceRecord(value, [
