	try {
		database = new DatabaseSync(`${primaryFilename}${DATABASE_SUFFIX}`, {
			allowExtension: false,
			enableDoubleQuotedStringLiterals: false,
			enableForeignKeyConstraints: false,
			readOnly: false,
